Definition RECat (m : word -> option byte) (p : Z) (fs : list fld) : Prop :=
  0 <= p /\ p + Z.of_nat (flds_len fs) < 2 ^ 64 /\ flds_wf fs /\ bytes_at m p (flds_bytes fs).

