Lemma flds_bytes_split : forall fs i, (i < length fs)%nat ->
  firstn (fst (fld_get fs i)) (skipn (fld_off fs i) (flds_bytes fs)) = Z_to_le_bytes (fst (fld_get fs i)) (snd (fld_get fs i)).
Proof.
