Lemma fld_set_bytes : forall fs i z, (i < length fs)%nat ->
  flds_bytes (fld_set fs i z) =
  firstn (fld_off fs i) (flds_bytes fs) ++ Z_to_le_bytes (fst (fld_get fs i)) z ++
  skipn (fld_off fs i + fst (fld_get fs i)) (flds_bytes fs).
Proof.
